package com.nyayaconnect.web;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;
public class SecurityHeadersFilter implements Filter {public void doFilter(ServletRequest q,ServletResponse p,FilterChain c)throws IOException,ServletException{HttpServletResponse s=(HttpServletResponse)p;s.setHeader("X-Content-Type-Options","nosniff");s.setHeader("X-Frame-Options","DENY");s.setHeader("Referrer-Policy","strict-origin-when-cross-origin");s.setHeader("Content-Security-Policy","default-src 'self'; style-src 'self' 'unsafe-inline'; frame-src 'self' https://meet.jit.si; connect-src 'self' https://meet.jit.si wss://meet.jit.si; media-src 'self' blob:; frame-ancestors 'none'; base-uri 'self'; form-action 'self'");s.setHeader("Permissions-Policy","camera=(self), microphone=(self), geolocation=()");c.doFilter(q,p);}}
